import React, { useEffect, useState } from "react";
import Chart from "./Chart"; // 先ほどのPlotlyコンポーネント
import axios from "axios";

type Row = {
  date: string;
  close: number | null;
  ma_5: number | null;
  ma_10: number | null;
  rsi: number | null;
  bb_upper: number | null;
  bb_lower: number | null;
};

const STOCK_OPTIONS = [
  { label: "エヌビディア", value: "NVDA" },
  { label: "イオンキュー", value: "IONQ" },
  { label: "Tesla", value: "TSLA" }
];

export default function StockChart() {
  const [rows, setRows] = useState<Row[]>([]);
  const [symbol, setSymbol] = useState("NVDA");
  const [loading, setLoading] = useState(false);

  const fetchData = async () => {
    setLoading(true);
    try {
      const response = await axios.post("http://127.0.0.1:8000/download_stock", { symbol });
      const data = response.data.map((d: any) => ({
        date: d.Date,
        close: d.Close ?? null,
        ma_5: d.SMA5 ?? null,
        ma_10: d.SMA25 ?? null,
        rsi: d.RSI14 ?? null,
        bb_upper: d.BB_UPPER ?? null,
        bb_lower: d.BB_LOWER ?? null
      }));
      setRows(data);
    } catch (error) {
      console.error(error);
      alert("データ取得に失敗しました");
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
  }, [symbol]);

  return (
    <div style={{ width: "95%", margin: "0 auto" }}>
      <form
        onSubmit={e => { e.preventDefault(); fetchData(); }}
        style={{ marginBottom: "20px" }}
      >
        <label>
          銘柄:
          <select value={symbol} onChange={e => setSymbol(e.target.value)}>
            {STOCK_OPTIONS.map(opt => (
              <option key={opt.value} value={opt.value}>{opt.label}</option>
            ))}
          </select>
        </label>
        <button type="submit" style={{ marginLeft: "10px" }}>
          {loading ? "読み込み中..." : "更新"}
        </button>
      </form>
      <Chart
        rows={rows}
        includeRsi={true}
        includeMa5={true}
        includeMa10={true}
        includeBb={true}
        isLight={true}
      />
    </div>
  );
}
